def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def boundaryTraversal(tree):
    vals, left, right = _links(tree)
    if not vals:
        return []

    def leaf(k):
        return left[k] == -1 and right[k] == -1

    if leaf(0):
        return [vals[0]]
    out = [vals[0]]
    k = left[0]
    while k != -1 and not leaf(k):
        out.append(vals[k])
        k = left[k] if left[k] != -1 else right[k]
    stack = [0]
    while stack:
        k = stack.pop()
        if leaf(k):
            out.append(vals[k])
        else:
            if right[k] != -1:
                stack.append(right[k])
            if left[k] != -1:
                stack.append(left[k])
    tail = []
    k = right[0]
    while k != -1 and not leaf(k):
        tail.append(vals[k])
        k = right[k] if right[k] != -1 else left[k]
    out.extend(reversed(tail))
    return out
